const staticData = $getWorkflowStaticData('global');

const subcategorias = [
  { cat: 'Cine Geek', pauta: 'Marvel MCU, Harry Potter, Star Wars o Animes famosos (Dragon Ball, Naruto, One Piece). Pregunta por un dato que solo los verdaderos fans conocen.' },
  { cat: 'Fútbol Élite', pauta: 'Champions League, Mundiales, Balón de Oro, récords históricos de Messi, Cristiano Ronaldo, Pelé o Maradona.' },
  { cat: 'Cultura General', pauta: 'Preguntas trampa que el 90% responde mal creyendo que es fácil. Récords Guinness, inventores o datos asombrosos del cuerpo humano.' },
  { cat: 'Historia Antigua', pauta: 'El Imperio Romano, gladiadores, mitología griega o civilizaciones perdidas. Pregunta por hechos reales poco conocidos.' },
  { cat: 'Ciencia y Espacio', pauta: 'Agujeros negros, el Sistema Solar, qué pasaría si la Tierra se detiene o misterios de las profundidades del océano.' },
  { cat: 'Geografía del Mundo', pauta: 'Capitales engañosas, países con fronteras curiosas, banderas parecidas o lugares extremos del planeta.' },
  { cat: 'Animales Extremos', pauta: 'Los animales más venenosos, criaturas prehistóricas, récords de fuerza o velocidad en el reino animal.' },
  { cat: 'Curiosidades del Mundo', pauta: 'Leyes absurdas de otros países, inventos por accidente o misterios históricos comprobados.' }
];

if (typeof staticData.subIdx === 'undefined') staticData.subIdx = 0;

const actual = subcategorias[staticData.subIdx];
staticData.subIdx = (staticData.subIdx + 1) % subcategorias.length;

return [{
  json: {
    categoria: actual.cat,
    pauta: actual.pauta,
    semilla: Math.floor(Math.random() * 10000)
  }
}];

